package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

const DefaultLowStockThreshold = 5

// configFileName is the config file name under a config/ directory.
const configFileName = "thresholds.json"

// LowStockThreshold returns the low-stock threshold for the warehouse,
// reading config/thresholds.json. Falls back to DefaultLowStockThreshold.
func LowStockThreshold(warehouse string) int {
	path, ok := findThresholdsFile()
	if !ok {
		return DefaultLowStockThreshold
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return DefaultLowStockThreshold
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return DefaultLowStockThreshold
	}
	threshold, ok := thresholds[warehouse]
	if !ok {
		return DefaultLowStockThreshold
	}
	return threshold
}
```

