package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFile 是配置目录下的阈值文件名。
const thresholdsFile = "thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值来自 `config/thresholds.json`：顶层是「仓库名 -> 阈值」的 JSON 对象。
// 仓库没配、文件不存在、读不出来或内容不是 JSON 对象时，一律回退到
// DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, ok := readThresholds()
	if !ok {
		return DefaultLowStockThreshold
	}
	threshold, ok := thresholds[warehouse]
	if !ok {
		return DefaultLowStockThreshold
	}
	return threshold
}

// readThresholds 从离当前目录最近的 `config/thresholds.json` 读取阈值。
//
// 从当前工作目录逐级向上找，这样不论从仓库根目录还是子目录（go test 会把
// 工作目录设成包目录）启动都能找到仓库级配置。
func readThresholds() (map[string]int, bool) {
	path, ok := findThresholdsFile()
	if !ok {
		return nil, false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, false
	}
	if thresholds == nil {
		// JSON `null` 能解析成 nil map，但它不是配置对象。
		return nil, false
	}
	return thresholds, true
}

// findThresholdsFile 从当前工作目录向上逐级查找 config/thresholds.json。
