package inventory_test

import (
	"os"
	"path/filepath"
	"testing"

	"example.com/inventory/inventory"
)

func writeConfig(t *testing.T, dir, body string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Join(dir, "config"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "config", "thresholds.json"), []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestTmpConfiguredAndUnconfigured(t *testing.T) {
	root := t.TempDir()
	writeConfig(t, root, `{"xian": 11}`)
	t.Chdir(root)
	if got := inventory.LowStockThreshold("xian"); got != 11 {
		t.Fatalf("xian = %d, want 11", got)
	}
	if got := inventory.LowStockThreshold("chengdu"); got != inventory.DefaultLowStockThreshold {
		t.Fatalf("chengdu = %d, want default", got)
	}
	if !inventory.IsLowStock("xian", 10) {
		t.Fatal("10 should be low for xian(11)")
	}
	if inventory.IsLowStock("xian", 11) {
		t.Fatal("11 should not be low (strict <)")
	}
}

func TestTmpWalkUpFromSubdir(t *testing.T) {
	root := t.TempDir()
	writeConfig(t, root, `{"xian": 7}`)
	sub := filepath.Join(root, "a", "b")
	if err := os.MkdirAll(sub, 0o755); err != nil {
		t.Fatal(err)
	}
	t.Chdir(sub)
	if got := inventory.LowStockThreshold("xian"); got != 7 {
		t.Fatalf("xian = %d, want 7", got)
	}
}

func TestTmpFallbacks(t *testing.T) {
	root := t.TempDir()
	t.Chdir(root)
	if got := inventory.LowStockThreshold("xian"); got != inventory.DefaultLowStockThreshold {
		t.Fatalf("missing file = %d, want default", got)
	}
	for _, body := range []string{`{`, `[]`, `"nope"`, `3`, `null`} {
		writeConfig(t, root, body)
		if got := inventory.LowStockThreshold("xian"); got != inventory.DefaultLowStockThreshold {
			t.Fatalf("body %q => %d, want default", body, got)
		}
	}
	writeConfig(t, root, `{}`)
	if got := inventory.LowStockThreshold("xian"); got != inventory.DefaultLowStockThreshold {
		t.Fatalf("empty object => %d, want default", got)
	}
}

